DO $$ DECLARE
  sid UUID := '00000000-0000-0000-0000-000000000001';
  cs_id UUID := 'a8004612-55ef-4304-bbc8-74295be72476';
BEGIN
  DELETE FROM quiz_responses WHERE question_id IN (SELECT id FROM questions WHERE subject_id=cs_id AND chapters::text LIKE '%ICT L%');
  DELETE FROM quiz_questions WHERE question_id IN (SELECT id FROM questions WHERE subject_id=cs_id AND chapters::text LIKE '%ICT L%');
  DELETE FROM questions WHERE subject_id=cs_id AND chapters::text LIKE '%ICT L%' AND deleted_at IS NULL;
END $$;
