  (sid, cs_id, 'mcq', 'To draw a square in Scratch, what angle must the sprite turn inside a "repeat 4" loop?', '[{"key": "A", "value": "\\(90^{\\circ}\\)", "correct": true}, {"key": "B", "value": "\\(120^{\\circ}\\)", "correct": false}, {"key": "C", "value": "\\(60^{\\circ}\\)", "correct": false}, {"key": "D", "value": "\\(45^{\\circ}\\)", "correct": false}]', 'A', 2, 'hard', '["ICT L1: Introduction to Programming"]', '["scratch", "geometry", "ict_level1"]', true),
  (sid, cs_id, 'mcq', 'To draw a circle in Scratch, how many times must the "move 1 steps" and "turn 1 degrees" commands be repeated inside a loop?', '[{"key": "A", "value": "360 times", "correct": true}, {"key": "B", "value": "repeat 360", "correct": true}, {"key": "C", "value": "180 times", "correct": false}, {"key": "D", "value": "90 times", "correct": false}]', 'B', 2, 'hard', '["ICT L1: Introduction to Programming"]', '["scratch", "geometry", "ict_level1"]', true),
  (sid, cs_id, 'mcq', 'According to the Scratch curriculum notes, Scratch projects can be exported to which formats?', '[{"key": "A", "value": "Exe, Apk, and Jar formats", "correct": true}, {"key": "B", "value": "Pdf, Odt, and Docx formats", "correct": false}, {"key": "C", "value": "Mp3, Wav, and Ogg formats", "correct": false}, {"key": "D", "value": "Png, Jpg, and Gimp formats", "correct": false}]', 'A', 2, 'hard', '["ICT L1: Introduction to Programming"]', '["scratch", "export", "ict_level1"]', true),
