  (sid, cs_id, 'mcq', 'In advanced Scratch programming, how is a variable defined?', '[{"key": "A", "value": "A named digital storage box where you can keep values (like numbers or text) that can change during program execution", "correct": true}, {"key": "B", "value": "A static backdrop that never changes during a program", "correct": false}, {"key": "C", "value": "The command block used to turn a sprite clockwise", "correct": false}, {"key": "D", "value": "The physical keyboard keys used to interact with a game", "correct": false}]', 'A', 2, 'easy', '["ICT L2: Programming"]', '["scratch", "variables", "ict_level2"]', true),
