  (sid, cs_id, 'mcq', 'In geometry, how is an ''Angle'' defined?', '[{"key": "A", "value": "A geometric figure formed by two rays that share a common endpoint called the vertex", "correct": true}, {"key": "B", "value": "A flat, two-dimensional surface that extends infinitely in all directions", "correct": false}, {"key": "C", "value": "A straight line segment connecting two distinct endpoints on a grid", "correct": false}, {"key": "D", "value": "The total distance around the boundaries of a closed polygon", "correct": false}]', 'A', 2, 'easy', '["ICT L2: Software Applications"]', '["geometry", "angles", "ict_level2"]', true),
  (sid, cs_id, 'mcq', 'How does ''Area'' differ from ''Perimeter'' in mathematical measurement?', '[{"key": "A", "value": "Area is the measure of flat space enclosed within a shape''s boundary, while Perimeter is the total length of the outer boundary line", "correct": true}, {"key": "B", "value": "Area is for 3D objects, while Perimeter is for 2D flat surfaces", "correct": false}, {"key": "C", "value": "Area is measured in linear units, while Perimeter is measured in square units", "correct": false}, {"key": "D", "value": "Area measures weight, while Perimeter measures liquid volume capacity", "correct": false}]', 'A', 2, 'easy', '["ICT L2: Software Applications"]', '["measurement", "geometry", "ict_level2"]', true),
