  (sid, cs_id, 'mcq', 'In word processor spell-checkers, what do the Red, Green, and Blue underlines indicate respectively?', '[{"key": "A", "value": "Red indicates spelling errors, Green indicates grammar errors, and Blue indicates contextual errors", "correct": true}, {"key": "B", "value": "Red indicates grammar errors, Green indicates spelling errors, and Blue indicates formatting errors", "correct": false}, {"key": "C", "value": "Red indicates spelling errors, Green indicates formatting errors, and Blue indicates system warnings", "correct": false}, {"key": "D", "value": "Red indicates hyperlink paths, Green indicates table headers, and Blue indicates footnotes", "correct": false}]', 'A', 2, 'medium', '["ICT L2: Digital Documentation"]', '["word_processor", "spellcheck", "ict_level2"]', true),
  (sid, cs_id, 'mcq', 'What is the standard keyboard shortcut used to open the ''Find and Replace'' dialog box in LibreOffice Writer?', '[{"key": "A", "value": "Ctrl+H", "correct": true}, {"key": "B", "value": "Ctrl+F", "correct": false}, {"key": "C", "value": "Ctrl+Z", "correct": false}, {"key": "D", "value": "Ctrl+P", "correct": false}]', 'A', 2, 'medium', '["ICT L2: Digital Documentation"]', '["word_processor", "shortcuts", "ict_level2"]', true),
  (sid, cs_id, 'mcq', 'What is the primary purpose of the ''Mail Merge'' facility in word processors?', '[{"key": "A", "value": "To efficiently create hundreds of personalized letters or labels by combining a standard template document with a structured data source", "correct": true}, {"key": "B", "value": "To automatically scan and clean email inbox storage", "correct": false}, {"key": "C", "value": "To compress text documents into smaller ZIP file packages", "correct": false}, {"key": "D", "value": "To send large file attachments to a contact list without using an ISP", "correct": false}]', 'A', 2, 'medium', '["ICT L2: Digital Documentation"]', '["word_processor", "mail_merge", "ict_level2"]', true),
  (sid, cs_id, 'mcq', 'Which two essential files are merged together during a Mail Merge process?', '[{"key": "A", "value": "A Main/Template Document (containing content and placeholders) and a Data Source (containing unique recipient details)", "correct": true}, {"key": "B", "value": "A System Software file and an Application Software package", "correct": false}, {"key": "C", "value": "A Text File (.txt) and a compressed image folder", "correct": false}, {"key": "D", "value": "A Spreadsheet math formula and an output PDF", "correct": false}]', 'A', 2, 'medium', '["ICT L2: Digital Documentation"]', '["word_processor", "mail_merge", "ict_level2"]', true),
  (sid, cs_id, 'mcq', 'In electronic spreadsheets, how does a Cell Reference differ from a Cell Range?', '[{"key": "A", "value": "A Cell Reference is the unique address of a single cell (e.g., A1), while a Cell Range is a collection of contiguous cells separated by a colon (e.g., A1:C5)", "correct": true}, {"key": "B", "value": "A Cell Reference represents rows, while a Cell Range represents columns", "correct": false}, {"key": "C", "value": "A Cell Reference is letters only, while a Cell Range is numbers only", "correct": false}, {"key": "D", "value": "A Cell Reference is for formulas, while a Cell Range is for functions", "correct": false}]', 'A', 2, 'medium', '["ICT L2: Digital Documentation"]', '["spreadsheet", "references", "ict_level2"]', true),
  (sid, cs_id, 'mcq', 'What value does the QUOTIENT function return when dividing two numbers in a spreadsheet?', '[{"key": "A", "value": "Only the integer portion of the result, discarding the remainder", "correct": true}, {"key": "B", "value": "The decimal remainder of the division only", "correct": false}, {"key": "C", "value": "The rounded average of the two numbers", "correct": false}, {"key": "D", "value": "The exact product of the numerator and denominator", "correct": false}]', 'A', 2, 'medium', '["ICT L2: Digital Documentation"]', '["spreadsheet", "functions", "ict_level2"]', true),
  (sid, cs_id, 'mcq', 'What are the coordinate values of the absolute center point (origin) on the Scratch Stage?', '[{"key": "A", "value": "\\(x = 0, y = 0\\)", "correct": true}, {"key": "B", "value": "\\(x = 240, y = 180\\)", "correct": false}, {"key": "C", "value": "\\(x = -240, y = -180\\)", "correct": false}, {"key": "D", "value": "\\(x = 100, y = 100\\)", "correct": false}]', 'A', 2, 'medium', '["ICT L2: Programming"]', '["scratch", "coordinates", "ict_level2"]', true),
  (sid, cs_id, 'mcq', 'In Scratch, what is the primary benefit of creating custom blocks using ''My Blocks''?', '[{"key": "A", "value": "It acts as a shortcut function to automate and organize repetitive task blocks under a single named block", "correct": true}, {"key": "B", "value": "It allows users to draw custom sprites from scratch", "correct": false}, {"key": "C", "value": "It translates Scratch projects into text-based Python code", "correct": false}, {"key": "D", "value": "It enables online multi-player connectivity with other schools", "correct": false}]', 'A', 2, 'medium', '["ICT L2: Programming"]', '["scratch", "functions", "ict_level2"]', true),
  (sid, cs_id, 'mcq', 'Who coined the term ''software'' in the year 1958?', '[{"key": "A", "value": "John W. Tukey", "correct": true}, {"key": "B", "value": "Tom Kilburn", "correct": false}, {"key": "C", "value": "Freddie Williams", "correct": false}, {"key": "D", "value": "Charles Babbage", "correct": false}]', 'A', 2, 'medium', '["ICT L2: Software Applications"]', '["software", "history", "ict_level2"]', true),
  (sid, cs_id, 'mcq', 'What is the primary role of ''System Software'' in a computer system?', '[{"key": "A", "value": "To manage, coordinate, and control computer hardware so that other user application software can run properly", "correct": true}, {"key": "B", "value": "To perform specific user-oriented tasks like document design or video playing", "correct": false}, {"key": "C", "value": "To browse websites on the World Wide Web", "correct": false}, {"key": "D", "value": "To compress files into smaller digital folders for email sharing", "correct": false}]', 'A', 2, 'medium', '["ICT L2: Software Applications"]', '["software", "classification", "ict_level2"]', true),
  (sid, cs_id, 'mcq', 'Which of the following consists ONLY of System Software?', '[{"key": "A", "value": "Operating Systems, Device Drivers, Firmware, and BIOS", "correct": true}, {"key": "B", "value": "MS Word, GIMP, Google Chrome, and LibreOffice Calc", "correct": false}, {"key": "C", "value": "Antivirus programs, Disk clean-up tools, and WinZip", "correct": false}, {"key": "D", "value": "Scratch, GeoGebra, Spotify, and Amazon Shopping", "correct": false}]', 'A', 2, 'medium', '["ICT L2: Software Applications"]', '["software", "examples", "ict_level2"]', true),
  (sid, cs_id, 'mcq', 'What is the function of Utility Software like Antivirus programs or Disk Defragmentation tools?', '[{"key": "A", "value": "To perform specific, system-maintenance tasks in the background to keep the computer system running smoothly and securely", "correct": true}, {"key": "B", "value": "To provide an interactive drawing canvas for traditional fine art", "correct": false}, {"key": "C", "value": "To translate written code from English into regional scripts", "correct": false}, {"key": "D", "value": "To connect to external websites and perform shopping transactions", "correct": false}]', 'A', 2, 'medium', '["ICT L2: Software Applications"]', '["software", "utility", "ict_level2"]', true),
  (sid, cs_id, 'mcq', 'What is GeoGebra, as described in the Level 2 textbook?', '[{"key": "A", "value": "An open-source dynamic mathematics software that integrates geometry, algebra, spreadsheets, graphing, statistics, and calculus", "correct": true}, {"key": "B", "value": "A visual program designed to build interactive 3D gaming scripts", "correct": false}, {"key": "C", "value": "A dedicated word processor for regional translation in Karnataka", "correct": false}, {"key": "D", "value": "A commercial antivirus and computer system optimization tool", "correct": false}]', 'A', 2, 'medium', '["ICT L2: Software Applications"]', '["learning_apps", "geogebra", "ict_level2"]', true),
  (sid, cs_id, 'mcq', 'In algebra, what is the correct standard sequence of operations represented by the acronym PEMDAS?', '[{"key": "A", "value": "Parentheses, Exponents, Multiplication and Division, Addition and Subtraction", "correct": true}, {"key": "B", "value": "Percent, Equations, Multiples, Division, Alignment, Sorting", "correct": false}, {"key": "C", "value": "Primary, External, Mixed, Decimal, Absolute, System", "correct": false}, {"key": "D", "value": "Power, Equal, Margins, Duplication, Area, Shapes", "correct": false}]', 'A', 2, 'medium', '["ICT L2: Software Applications"]', '["algebra", "pemdas", "ict_level2"]', true),
  (sid, cs_id, 'mcq', 'In the Level 2 syllabus, which statement best defines the role of communication technology?', '[{"key": "A", "value": "Exchanging messages, data, or media electronically over a network", "correct": true}, {"key": "B", "value": "Printing textual documents in black and white format", "correct": false}, {"key": "C", "value": "Adding 3D shapes to a slideshow presentation", "correct": false}, {"key": "D", "value": "Manually adjusting the color levels of an image in GIMP", "correct": false}]', 'A', 2, 'medium', '["ICT L2: Internet and ICT Environment"]', '["communication", "auto", "ict_level2"]', true),
  (sid, cs_id, 'mcq', 'In image manipulation software like GIMP, how does "Crop to Content" differ from "Crop to Selection"?', '[{"key": "A", "value": "Crop to Content automatically detects the main subject and removes empty background areas without manual selection, whereas Crop to Selection crops strictly to user-defined boundaries", "correct": true}, {"key": "B", "value": "Crop to Content requires a manual selection tool, whereas Crop to Selection is fully automated by GIMP", "correct": false}, {"key": "C", "value": "Crop to Content expands the boundaries of the canvas, whereas Crop to Selection reduces them", "correct": false}, {"key": "D", "value": "Crop to Content changes the file format of the image, whereas Crop to Selection changes the resolution", "correct": false}]', 'A', 2, 'hard', '["ICT L2: Graphics in ICT"]', '["gimp", "cropping", "ict_level2"]', true),
  (sid, cs_id, 'mcq', 'Which image transformation tool slants/tilts an image horizontally or vertically while strictly maintaining its original dimensions, parallel lines, and fixed boundaries without expanding the canvas?', '[{"key": "A", "value": "Shear", "correct": true}, {"key": "B", "value": "Skew", "correct": false}, {"key": "C", "value": "Perspective", "correct": false}, {"key": "D", "value": "Rotate", "correct": false}]', 'A', 2, 'hard', '["ICT L2: Graphics in ICT"]', '["gimp", "transformations", "ict_level2"]', true),
  (sid, cs_id, 'mcq', 'In spreadsheets, how are text entries starting with special characters or numbers handled during a standard ascending sort?', '[{"key": "A", "value": "They are sorted and displayed before entries starting with alphabetical letters", "correct": true}, {"key": "B", "value": "They are completely ignored and hidden from the table view", "correct": false}, {"key": "C", "value": "They are placed at the very end of the sorted list, after alphabetical letters", "correct": false}, {"key": "D", "value": "They cause an error flag because they do not contain text letters", "correct": false}]', 'A', 2, 'hard', '["ICT L2: Digital Documentation"]', '["spreadsheet", "sorting", "ict_level2"]', true),
  (sid, cs_id, 'mcq', 'What are the total width, height, and coordinate ranges of the standard Scratch stage?', '[{"key": "A", "value": "The stage size is \\(480 \\times 360\\) pixels, where \\(x\\) ranges from \\(-240\\) to \\(240\\), and \\(y\\) ranges from \\(-180\\) to \\(180\\)", "correct": true}, {"key": "B", "value": "The stage size is \\(1000 \\times 1000\\) pixels, where \\(x\\) ranges from \\(0\\) to \\(1000\\), and \\(y\\) ranges from \\(0\\) to \\(1000\\)", "correct": false}, {"key": "C", "value": "The stage size is \\(360 \\times 240\\) pixels, where \\(x\\) ranges from \\(-180\\) to \\(180\\), and \\(y\\) ranges from \\(-120\\) to \\(120\\)", "correct": false}, {"key": "D", "value": "The stage size is \\(640 \\times 480\\) pixels, where \\(x\\) ranges from \\(-320\\) to \\(320\\), and \\(y\\) ranges from \\(-240\\) to \\(240\\)", "correct": false}]', 'A', 2, 'hard', '["ICT L2: Programming"]', '["scratch", "coordinates", "ict_level2"]', true),
  (sid, cs_id, 'mcq', 'Who created the first-ever computer program/software on the Manchester SSEM computer in 1948?', '[{"key": "A", "value": "Tom Kilburn", "correct": true}, {"key": "B", "value": "John W. Tukey", "correct": false}, {"key": "C", "value": "Steve Jobs", "correct": false}, {"key": "D", "value": "Bill Gates", "correct": false}]', 'A', 2, 'hard', '["ICT L2: Software Applications"]', '["software", "history", "ict_level2"]', true),
  (sid, cs_id, 'mcq', 'In a word processor, where is your working file stored temporarily before you select the ''Save'' command to write it to the hard drive?', '[{"key": "A", "value": "In volatile RAM, which loses all data if power is lost", "correct": true}, {"key": "B", "value": "On the secure hard disk drive directly", "correct": false}, {"key": "C", "value": "In the permanent BIOS chip settings", "correct": false}, {"key": "D", "value": "In the cloud backup server", "correct": false}]', 'A', 2, 'hard', '["ICT L2: Software Applications"]', '["hardware", "memory", "ict_level2"]', true),
  (sid, cs_id, 'mcq', 'Who started the GeoGebra project in 2001 as part of a master''s thesis at the University of Salzburg?', '[{"key": "A", "value": "Markus Hohenwarter", "correct": true}, {"key": "B", "value": "John W. Tukey", "correct": false}, {"key": "C", "value": "Tom Kilburn", "correct": false}, {"key": "D", "value": "Dr. Rajaram Sharma", "correct": false}]', 'A', 2, 'hard', '["ICT L2: Software Applications"]', '["geogebra", "history", "ict_level2"]', true),
